<?php
declare(strict_types=1);
namespace App\Services;

use App\Models\{AuditLog,PurchaseReturn,PurchaseReturnCorrection,SupplierCreditReturnCorrection,User};
use App\Support\Decimal as D;
use DomainException;
use PDO;

/** Immutable, evidenced physical restoration of a posted purchase return. Financial credits remain out of scope. */
final class PurchaseReturnCorrectionService
{
    public function __construct(private PDO $pdo,private User $users,private AuditLog $audit,private PurchaseReturn $returns,
        private PurchaseReturnCorrection $corrections,private InventoryService $inventory,private SupplierCreditReturnCorrection $financialCorrections) {}

    public function createDraft(int $actor,array $input): array
    {
        $this->permission($actor,'request'); $this->keys($input,['_csrf','document_key','purchase_return_id','reason','evidence_reference','items']);
        $return=$this->id($input['purchase_return_id']??null); $key=$this->key($input['document_key']??null); $reason=$this->reason($input['reason']??null); $evidence=$this->evidence($input['evidence_reference']??null);
        if (!is_array($input['items']??null) || !$input['items'] || count($input['items'])>100) { throw new DomainException('A correction needs 1-100 returned lines.'); }
        $requested=[];
        foreach ($input['items'] as $line) { if(!is_array($line)){throw new DomainException('Invalid correction line.');} $this->keys($line,['purchase_return_posting_id','quantity','evidence_reference']); $post=$this->id($line['purchase_return_posting_id']??null); if(isset($requested[$post])){throw new DomainException('Each return posting may occur once per correction.');} $requested[$post]=[D::positive($this->text($line['quantity']??null),3),$this->evidence($line['evidence_reference']??null)]; }
        ksort($requested,SORT_NUMERIC); $hash=$this->digest([$return,$reason,$evidence,$requested]);
        return $this->transaction(function() use($actor,$return,$key,$reason,$evidence,$requested,$hash): array {
            $original=$this->lockReturn($return); $existing=$this->corrections->byKey($key);
            if($existing){ if((int)$existing['created_by']!==$actor || $existing['request_hash']!==$hash){throw new DomainException('Correction key belongs to another request.');} return ['correction_id'=>(int)$existing['id'],'created'=>false]; }
            $items=[];
            foreach($requested as $postingId=>[$quantity,$lineEvidence]) { $source=$this->corrections->source($postingId,true); $this->assertSource($source,$original); $quantity=$this->quantity($quantity,(int)$source['unit_precision_snapshot']); $base=D::positive(D::multiply($quantity,$source['conversion_snapshot'],3),3); $this->remaining($source,$quantity,$base); $items[]=['purchase_return_posting_id'=>$postingId,'return_item_id'=>(int)$source['return_item_id'],'product_id'=>(int)$source['product_id'],'location_id'=>(int)$source['location_id'],'quantity'=>$quantity,'qty_base'=>$base,'conversion_snapshot'=>$source['conversion_snapshot'],'unit_precision_snapshot'=>(int)$source['unit_precision_snapshot'],'original_unit_cost_khr'=>$source['unit_cost_khr'],'original_carrying_value_khr'=>$source['carrying_value_khr'],'evidence_reference'=>$lineEvidence]; }
            $id=$this->corrections->create(['correction_no'=>'PRC-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(6))),'document_key'=>$key,'request_hash'=>$hash,'purchase_return_id'=>$return,'reason'=>$reason,'evidence_reference'=>$evidence,'created_by'=>$actor]);
            foreach($items as $item){$this->corrections->createItem(['correction_id'=>$id]+$item);} $this->audit->record($actor,'purchase_return_correction.draft_created','purchase_return_corrections',$id); return ['correction_id'=>$id,'created'=>true];
        });
    }
    public function submit(int $actor,int $id): array { $this->permission($actor,'request'); return $this->transaction(function()use($actor,$id):array{$doc=$this->locked($id); if(!$this->users->isOwner($actor)&&(int)$doc['created_by']!==$actor){throw new DomainException('Only the requester or Owner may submit this correction.');} if($doc['status']==='submitted'){return ['correction_id'=>$id,'submitted'=>false];} $this->state($doc,['draft']);$this->validate($doc,$this->corrections->items($id,true));$this->corrections->transition($doc,'submitted',$actor);$this->audit->record($actor,'purchase_return_correction.submitted','purchase_return_corrections',$id);return ['correction_id'=>$id,'submitted'=>true];}); }
    public function approve(int $actor,int $id): array { $this->owner($actor,'approve'); return $this->transaction(function()use($actor,$id):array{$doc=$this->locked($id);$items=$this->corrections->items($id,true);if($doc['status']==='approved'){$this->approved($doc,$items);return ['correction_id'=>$id,'approved'=>false];}$this->state($doc,['submitted']);$this->validate($doc,$items);$this->corrections->approve($id,$this->contentHash($doc,$items),$actor);$this->corrections->transition($doc,'approved',$actor);$this->audit->record($actor,'purchase_return_correction.approved','purchase_return_corrections',$id);return ['correction_id'=>$id,'approved'=>true];}); }
    public function post(int $actor,int $id): array { $this->owner($actor,'post'); return $this->transaction(function()use($actor,$id):array{$doc=$this->locked($id);$items=$this->corrections->items($id,true);$this->approved($doc,$items);if($doc['status']==='posted'){$this->assertPostingEvidence($doc,$items);return ['correction_id'=>$id,'posted'=>false];}$this->state($doc,['approved']);$values=$this->validate($doc,$items);$posted=$this->inventory->postLockedPurchaseReturnCorrection($actor,$doc,$values);foreach($values as $item){$id=(int)$item['id'];$q=$posted[$id];$this->corrections->post(['correction_item_id'=>$id,'stock_movement_id'=>$q['movement_id'],'posting_key'=>'purchase-return-correction:'.$doc['id'].':'.$id,'quantity'=>$item['quantity'],'qty_base'=>$item['qty_base'],'unit_cost_khr'=>$q['unit_cost_khr'],'carrying_value_khr'=>$item['carrying_value_khr'],'posted_by'=>$actor]);}$this->corrections->markPosted((int)$doc['id'],$actor);$this->audit->record($actor,'purchase_return_correction.posted','purchase_return_corrections',$doc['id']);return ['correction_id'=>$doc['id'],'posted'=>true];}); }
    public function reject(int $actor,int $id,string $reason): void {$this->terminate($actor,$id,'rejected',$reason);} public function cancel(int $actor,int $id,string $reason):void{$this->terminate($actor,$id,'cancelled',$reason);}
    private function terminate(int $actor,int $id,string $to,string $reason):void{$this->owner($actor,'approve');$reason=$this->reason($reason);$this->transaction(function()use($actor,$id,$to,$reason):void{$doc=$this->locked($id);$this->state($doc,$to==='rejected'?['submitted','approved']:['draft','submitted','approved','rejected']);if($this->corrections->postings($id)){throw new DomainException('Posted correction history cannot be cancelled or rejected.');}$this->corrections->transition($doc,$to,$actor,$reason);$this->audit->record($actor,'purchase_return_correction.'.$to,'purchase_return_corrections',$id,$reason);});}
    public function forViewer(int $actor,int $id):array{$this->permission($actor,'view');$doc=$this->corrections->find($id);if(!$doc){throw new DomainException('Purchase return correction not found.');}$items=$this->corrections->items($id);if(!$this->users->isOwner($actor)){$doc=array_intersect_key($doc,array_flip(self::PUBLIC_HEADER));$items=array_map(fn($i)=>array_intersect_key($i,array_flip(self::PUBLIC_ITEM)),$items);}else{$doc['approval']=$this->corrections->approval($id);$doc['postings']=$this->corrections->postings($id);}return $doc+['items'=>$items];}
    public function listForViewer(int $actor,int $returnId):array{$this->permission($actor,'view');$rows=$this->corrections->list($returnId);return $this->users->isOwner($actor)?$rows:array_map(fn($r)=>array_intersect_key($r,array_flip(self::PUBLIC_HEADER)),$rows);}
    /** Read-only evidence report; it flags, but never fixes, physical/financial inconsistencies. */
    public function reconcile(int $actor,int $purchaseId):array{$this->owner($actor,'reconcile');return $this->transaction(function()use($purchaseId):array{$issues=[];$rows=$this->corrections->evidenceForPurchase($purchaseId);$net=[];foreach($rows as $r){$key=(int)$r['purchase_return_posting_id'];$net[$key]??=['returned'=>$r['original_carrying_value_khr'],'corrected_quantity'=>'0.000','corrected_value'=>'0.0000'];if($r['status']==='posted'){$bad=!$r['posting_id']||$r['posting_key']!=='purchase-return-correction:'.$r['correction_id'].':'.$r['correction_item_id']||$r['movement_qty']!==$r['posted_base']||$r['cost_qty']!==$r['posted_base']||$r['cost_value']!==$r['posted_value']||$r['movement_product']!=$r['product_id']||$r['movement_location']!=$r['location_id']||$r['movement_source']!=='purchase_return_correction'||(int)$r['movement_source_id']!==(int)$r['correction_id']||(int)$r['movement_source_line']!==(int)$r['correction_item_id']||$r['cost_source']!=='purchase_return_correction'||(int)$r['cost_source_id']!==(int)$r['correction_id']||(int)$r['cost_source_line']!==(int)$r['correction_item_id'];if($bad){$issues[]='Correction line '.$r['correction_item_id'].' evidence is inconsistent.';}$net[$key]['corrected_quantity']=D::add($net[$key]['corrected_quantity'],$r['quantity'],3);$net[$key]['corrected_value']=D::add($net[$key]['corrected_value'],$r['posted_value'],4);}elseif($r['posting_id']){$issues[]='Unposted correction has immutable posting evidence.';}}foreach(array_keys($net) as $posting){try{$source=$this->corrections->source($posting);if(!$source){throw new DomainException('Missing original return source.');}$this->financialCapacity($source,'0.000','0.000');}catch(DomainException $e){$issues[]=$e->getMessage();}}return ['purchase_id'=>$purchaseId,'corrections'=>$rows,'net_by_return_posting'=>$net,'issues'=>array_values(array_unique($issues)),'reconciled'=>$issues===[]];},true);}
    private function validate(array $doc,array $items):array{$original=$this->lockReturn((int)$doc['purchase_return_id']);$this->approved($doc,$items,false);$result=[];foreach($items as $item){$source=$this->corrections->source((int)$item['purchase_return_posting_id'],true);$this->assertSource($source,$original);if((int)$source['return_item_id']!==(int)$item['return_item_id']||(int)$source['product_id']!==(int)$item['product_id']||(int)$source['location_id']!==(int)$item['location_id']||$source['conversion_snapshot']!==$item['conversion_snapshot']||(int)$source['unit_precision_snapshot']!==(int)$item['unit_precision_snapshot']){throw new DomainException('Correction item differs from original return evidence.');}$qty=$this->quantity($item['quantity'],(int)$item['unit_precision_snapshot']);$base=D::positive(D::multiply($qty,$item['conversion_snapshot'],3),3);if($base!==$item['qty_base']){throw new DomainException('Correction base quantity differs from the saved conversion.');}$this->remaining($source,$qty,$base);$this->financialCapacity($source,$qty,$base);$used=$this->corrections->usage((int)$source['id']);$value=$this->share($source['carrying_value_khr'],D::add($used['quantity'],$qty,3),$source['quantity'],$used['carrying_value_khr']);$result[]=$item+['carrying_value_khr'=>$value];}return $result;}
    private function assertSource(?array $s,array $return):void{if(!$s||(int)$s['return_id']!==(int)$return['id']||$return['status']!=='confirmed'||$s['return_status']!=='confirmed'||!$s['confirmed_at']||!$s['stock_movement_id']||$s['movement_qty']!=='-'.$s['qty_base']||$s['cost_qty']!=='-'.$s['qty_base']||$s['cost_value']!=='-'.$s['carrying_value_khr']||$s['movement_cost']!==$s['unit_cost_khr']||$s['source_type']!=='purchase_return'||(int)$s['source_id']!==(int)$s['return_id']||(int)$s['source_line_id']!==(int)$s['return_item_id']||$s['cost_source_type']!=='purchase_return'||(int)$s['cost_source_id']!==(int)$s['return_id']||(int)$s['cost_source_line']!==(int)$s['return_item_id']||$s['costing_type']!=='purchase_return'){throw new DomainException('Original purchase-return stock and valuation evidence is unsupported.');}}
    private function remaining(array $source,string $qty,string $base):void{$used=$this->corrections->usage((int)$source['id']);if(D::compare(D::add($used['quantity'],$qty,3),$source['quantity'],3)>0||D::compare(D::add($used['qty_base'],$base,3),$source['qty_base'],3)>0){throw new DomainException('Correction exceeds original returned quantity less previous posted corrections.');}}
    /** P5.8 releases only the exact financial-link quantity; unlinked physical quantity remains eligible. */
    private function financialCapacity(array $source,string $qty,string $base):void{$links=$this->returns->linksForItem((int)$source['return_item_id']);$linked='0.000';$linkedBase='0.000';foreach($links as $link){$linked=D::add($linked,$link['quantity'],3);$linkedBase=D::add($linkedBase,$link['qty_base'],3);}$released=$this->financialCorrections->physicalCapacity((int)$source['id']);$allowed=D::add(D::subtract($source['quantity'],$linked,3),$released['quantity'],3);$allowedBase=D::add(D::subtract($source['qty_base'],$linkedBase,3),$released['qty_base'],3);$used=$this->corrections->usage((int)$source['id']);if(D::compare(D::add($used['quantity'],$qty,3),$allowed,3)>0||D::compare(D::add($used['qty_base'],$base,3),$allowedBase,3)>0){throw new DomainException('Linked supplier-credit quantity requires an exact posted financial correction before inventory can be restored.');}}
    private function assertPostingEvidence(array $doc,array $items):void{$posts=array_column($this->corrections->postings((int)$doc['id']),null,'correction_item_id');if(count($posts)!==count($items)){throw new DomainException('Posted correction evidence is incomplete.');}}
    private function lockReturn(int $id):array{$r=$this->returns->find($id,true);if(!$r||$r['status']!=='confirmed'){throw new DomainException('Only a confirmed purchase return may be corrected.');}return $r;}
    private function locked(int $id):array{$doc=$this->corrections->find($id,true);if(!$doc){throw new DomainException('Purchase return correction not found.');}$this->lockReturn((int)$doc['purchase_return_id']);return $doc;}
    private function approved(array $doc,array $items,bool $require=true):void{if(!$require)return;$a=$this->corrections->approval((int)$doc['id']);if(!$a||$a['content_hash']!==$this->contentHash($doc,$items)||(int)$a['approved_by']!==(int)$doc['approved_by']){throw new DomainException('Correction differs from its immutable Owner approval.');}}
    private function contentHash(array $doc,array $items):string{$head=array_intersect_key($doc,array_flip(['id','purchase_return_id','reason','evidence_reference','created_by']));ksort($head);foreach($items as &$item){ksort($item);}unset($item);return $this->digest([$head,$items]);}
    private function share(string $value,string $cumulative,string $total,string $used):string{$scale=max(strlen(explode('.',$cumulative)[1]??''),strlen(explode('.',$total)[1]??''));$target=D::compare($cumulative,$total,$scale)===0?D::nonNegative($value,4):D::divide(D::multiplyRounded($value,$cumulative,10,40),$total,4);return D::subtract($target,D::nonNegative($used,4),4);}
    private function state(array $doc,array $allowed):void{if(!in_array($doc['status'],$allowed,true)){throw new DomainException('Invalid purchase-return correction state transition.');}}
    private function permission(int $actor,string $action):void{if(!$this->users->findActiveById($actor)||!$this->users->hasPermission($actor,'purchase_return_corrections.'.$action)){throw new DomainException('Not authorized for this purchase-return correction action.');}}
    private function owner(int $actor,string $action):void{$this->permission($actor,$action);if(!$this->users->isOwner($actor)){throw new DomainException('Only an active Owner may approve, post or reconcile purchase-return corrections.');}}
    private function id(mixed $id):int{if(!is_scalar($id)||filter_var($id,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])===false){throw new DomainException('A positive record identifier is required.');}return(int)$id;}
    private function text(mixed $v):string{if(!is_string($v)&&!is_int($v)){throw new DomainException('Text/decimal input is required.');}return(string)$v;}
    private function reason(mixed $v):string{$v=trim($this->text($v));if(strlen($v)<3||strlen($v)>500){throw new DomainException('A reason of 3-500 bytes is required.');}return$v;}
    private function evidence(mixed $v):string{$v=trim($this->text($v));if(strlen($v)<3||strlen($v)>500){throw new DomainException('A supporting evidence reference of 3-500 bytes is required.');}return$v;}
    private function key(mixed $v):string{$v=$this->text($v);if(!preg_match('/^[A-Za-z0-9_-]{8,80}$/',$v)){throw new DomainException('A request key of 8-80 letters, digits, dashes or underscores is required.');}return$v;}
    private function quantity(string $v,int $precision):string{if($precision<0||$precision>3){throw new DomainException('Unsupported return unit precision.');}$v=str_contains($v,'.')?rtrim(rtrim($v,'0'),'.'):$v;return D::positive(D::positive($v,$precision),3);}
    private function keys(array $input,array $allowed):void{if(array_diff(array_keys($input),$allowed)){throw new DomainException('Unsupported input. Correction requests accept only quantities, reasons and evidence references.');}}
    private function digest(array $v):string{return hash('sha256',json_encode($v,JSON_THROW_ON_ERROR));}
    private const PUBLIC_HEADER=['id','correction_no','purchase_return_id','status','created_by','created_at','submitted_at','posted_at'];
    private const PUBLIC_ITEM=['id','correction_id','purchase_return_posting_id','return_item_id','product_id','location_id','quantity','qty_base','conversion_snapshot','unit_precision_snapshot'];
    private function transaction(callable $op,bool $readOnly=false):mixed{if($this->pdo->inTransaction()){throw new \LogicException('Purchase-return correction service requires its own transaction.');}$this->pdo->exec('SET TRANSACTION ISOLATION LEVEL '.($readOnly?'REPEATABLE READ':'READ COMMITTED'));if($readOnly){$this->pdo->exec('SET TRANSACTION READ ONLY');}$this->pdo->beginTransaction();try{$r=$op();$this->pdo->commit();return$r;}catch(\Throwable $e){if($this->pdo->inTransaction()){$this->pdo->rollBack();}if($e instanceof \PDOException){throw new DomainException('Purchase-return correction conflicted with existing records. No changes were committed.',0,$e);}throw$e;}}
}
